let (tx, rx) = sync_channel::<Msg>(10_000);            // bound = capacity
match tx.try_send(msg) {
    Ok(()) => {}
    Err(TrySendError::Full(msg)) => { dropped += 1; }          // full: value handed back
    Err(TrySendError::Disconnected(msg)) => shut_down(msg),    // consumer is gone
}
// tx.send(msg) blocks instead; rx.recv() blocks while the buffer is empty

