let (tx, mut rx) = mpsc::channel::<Msg>(10_000);   // capacity 0 panics: the bound is mandatory
tokio::spawn(async move { while let Some(m) = rx.recv().await { process(m).await } });
match tx.try_send(msg) {
    Ok(()) => {}
    Err(TrySendError::Full(_)) => dropped += 1,     // full: shed instead of awaiting room
    Err(TrySendError::Closed(_)) => return,
}
